import (
	Shared from "@std/concurrency/shared.ms",
	Read from "./contracts.ms",
)

export interface Original:
	fn original() Int

export type Item:
	value: Int

impl Original for Item:
	fn original() Int:
		return self.value

export type Box[T]:
	value: T

export type Holder[T: Read[Int]]:
	value: T

impl Read[Int] for Holder[T]:
	fn get() Int:
		return self.value.get()

export enum Choice:
	Some(value: Int)
	Empty

export type Resource:
	events: Shared[List[Int]]
